mapper.select:
select id, task_id, interface_id, file_name, file_type, file_length,
       local_path, object_name, file_url, process_status,
       retry_count, last_error, next_retry_time,
       completed_time, create_time, update_time
from fep_file_transfer_record
where task_id = #{taskId}
  and interface_id = #{interfaceId}
  and file_name = #{fileName}
  and file_length = #{fileLength}
